@startuml

class HospitalHouseMD {}

class Patient {
  + Id : string
  + Name : string
}

class Doctor {
  + Id : string
  + Name : string
}

class HeadDoctor extends Doctor {}

class Diagnosis {
  + Id : string
  + Description : string
}

class Treatment {
  + Id : string
  + Name : string
  + Stage : int
}

class Illness {
  + Id : string
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  HIGH
  LOW
}

class ConsentForm {
  + Id : string
  + DateSigned : date
  + IsRetracted : boolean
}

HospitalHouseMD "1" *-- "*" Patient
HospitalHouseMD "1" *-- "*" Doctor
Patient "1" -- "*" Doctor
Patient "1" -- "*" Diagnosis
Doctor "1" -- "*" Diagnosis
Doctor "1" -- "*" Treatment
Diagnosis "1" -- "*" Treatment
Illness "1" -- "*" Diagnosis
Illness "1" -- "*" Treatment
Patient "1" -- "*" ConsentForm
ConsentForm "1" -- "1" Treatment

@enduml

